      "cents": 250,
      "qty": 2
    },
    {
      "name": "ink",
      "cents": 120,
      "qty": 1
    }
  ],
  "discount": 0.1,
  "share": 0.3333333333333333
}
$ ./order 2> /dev/null | jq -r .note
